class Solution {
public:
    int maximumValue(vector<string>& strs) {
        int ans = 0;
        for (auto& s : strs) {
            bool digitsOnly = true;
            for (char c : s)
                if (!isdigit(c)) { digitsOnly = false; break; }
            int v = digitsOnly ? stoi(s) : (int)s.size();
            ans = max(ans, v);
        }
        return ans;
    }
};

