class Solution {
    public int maximumValue(String[] strs) {
        int ans = 0;
        for (String s : strs) {
            boolean digitsOnly = true;
            for (char c : s.toCharArray()) {
                if (!Character.isDigit(c)) { digitsOnly = false; break; }
            }
            int v = digitsOnly ? Integer.parseInt(s) : s.length();
            ans = Math.max(ans, v);
        }
        return ans;
    }
}

