var maximumValue = function(strs) {
    let ans = 0;
    for (const s of strs) {
        const digitsOnly = /^[0-9]+$/.test(s);
        const v = digitsOnly ? parseInt(s, 10) : s.length;
        ans = Math.max(ans, v);
    }
    return ans;
};

