class Solution {
public:
    int maximumValue(vector<string>& strs) {
        int ans = 0;
        for (auto& s : strs) {
            bool hasAlpha = any_of(s.begin(), s.end(), [](char c){ return isalpha(c); });
            ans = max(ans, hasAlpha ? (int)s.size() : stoi(s));
        }
        return ans;
    }
};

