import java.util.stream.*;
class Solution {
    public int maximumValue(String[] strs) {
        return Arrays.stream(strs)
            .mapToInt(s -> s.chars().anyMatch(Character::isAlpha)
                ? s.length() : Integer.parseInt(s))
            .max().getAsInt();
    }
}

